import importlib.util, collections
sp=importlib.util.spec_from_file_location('m','programs/task-2854bf61.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
fixtures=[]
for ir,orr in zip(m.DEMO_INPUTS,m.DEMO_OUTPUTS):
 I=m._parse(ir);O=m._parse(orr)
 coords=[(r,c) for r in range(1,12,2) for c in [1,4,7,10,13]]
 A=[[int(I[r][c]==0) for c in [1,4,7,10,13]] for r in range(1,12,2)]
 B=[[int(O[r][c]==0) for c in [1,4,7,10,13]] for r in range(1,12,2)]
 fixtures.append((A,B))
# full Moore neighborhood local function conflicts
for rad in [1]:
 mp=collections.defaultdict(set); examples=0
 for A,B in fixtures:
  for r in range(6):
   for c in range(5):
    key=tuple(A[rr][cc] if 0<=rr<6 and 0<=cc<5 else 0 for rr in range(r-1,r+2) for cc in range(c-1,c+2))
    mp[key].add(B[r][c]);examples+=1
 print('moore neighborhoods',examples,'unique',len(mp),'conflicts',sum(len(v)>1 for v in mp.values()))
 # common Life-like rule output, compare variants of boundary 0 vs wrap
 for wrap in [False,True]:
  for birth in range(9):
   for surv in range(9):
    good=tot=0
    for A,B in fixtures:
     for r in range(6):
      for c in range(5):
       neighbors=[]
       for dr in [-1,0,1]:
        for dc in [-1,0,1]:
         if dr==dc==0:continue
         rr,cc=r+dr,c+dc
         if wrap: rr%=6;cc%=5
         neighbors.append(A[rr][cc] if 0<=rr<6 and 0<=cc<5 else 0)
       n=sum(neighbors);pred=int(n== (surv if A[r][c] else birth))
       good += pred==B[r][c];tot+=1
    if good>100:print('life',wrap,birth,surv,good,'/',tot)
# rowwise matching/shift results
for di,(A,B) in enumerate(fixtures):
 print('demo',di+1)
 for i,(x,y) in enumerate(zip(A,B)):
  s=[]
  for j,z in enumerate(A):
   for shift in range(-4,5):
    q=[z[(k+shift)%5] for k in range(5)]
    if q==y:s.append((j,shift))
